/** Read-only workbook rendering: no financial records are changed by exports. */
@RestController @RequestMapping("/api/export") public class ExcelExport {
 private final Api api;public ExcelExport(Api api){this.api=api;}
 @ExceptionHandler(Api.Fail.class) public ResponseEntity<?> fail(Api.Fail e){return api.fail(e);}
 private XSSFCellStyle style(XSSFWorkbook w,boolean bold,String fill,HorizontalAlignment align,String format){var s=w.createCellStyle();var f=w.createFont();f.setFontName("Arial");f.setFontHeightInPoints((short)11);f.setBold(bold);f.setColor(new XSSFColor(java.awt.Color.decode("#183651"),null));s.setFont(f);s.setAlignment(align);s.setVerticalAlignment(VerticalAlignment.CENTER);s.setWrapText(true);for(var b:List.of("top","bottom","left","right")){switch(b){case "top"->s.setBorderTop(BorderStyle.THIN);case "bottom"->s.setBorderBottom(BorderStyle.THIN);case "left"->s.setBorderLeft(BorderStyle.THIN);case "right"->s.setBorderRight(BorderStyle.THIN);}}if(fill!=null){s.setFillForegroundColor(new XSSFColor(java.awt.Color.decode(fill),null));s.setFillPattern(FillPatternType.SOLID_FOREGROUND);}if(format!=null)s.setDataFormat(w.createDataFormat().getFormat(format));return s;}
 private void banner(XSSFSheet s,int row,int cols,String text,XSSFCellStyle style,float height){var r=s.createRow(row);r.setHeightInPoints(height);for(int c=0;c<cols;c++){var x=r.createCell(c);x.setCellStyle(style);if(c==0)x.setCellValue(text);}if(cols>1)s.addMergedRegion(new CellRangeAddress(row,row,0,cols-1));}
 @PostMapping("/xlsx") public ResponseEntity<byte[]> export(@RequestBody Map<String,Object> body,HttpServletRequest request)throws Exception{
 api.auth(request,false);if(!(body.get("rows") instanceof List<?> raw)||raw.isEmpty()||raw.size()>20001)throw new Api.Fail(400,"Báo cáo tối đa 20.000 dòng");
 var rows=new ArrayList<List<?>>();int cols=0;long cells=0;for(Object o:raw){if(!(o instanceof List<?> r))throw new Api.Fail(400,"Dữ liệu xuất không hợp lệ");cols=Math.max(cols,r.size());cells+=r.size();if(r.stream().anyMatch(v->v!=null&&!(v instanceof String)&&!(v instanceof Number)&&!(v instanceof Boolean)))throw new Api.Fail(400,"Kiểu dữ liệu không hợp lệ");for(Object v:r)if(v instanceof String t&&t.length()>32000)throw new Api.Fail(400,"Nội dung ô quá dài");rows.add(r);}if(cols<1||cols>100||cells>500000)throw new Api.Fail(400,"Báo cáo quá lớn");
 if(cols!=rows.getFirst().size())throw new Api.Fail(400,"Số cột dữ liệu vượt đầu bảng");
 String title=Objects.toString(body.get("title"),"BÁO CÁO THU CHI"),subtitle=Objects.toString(body.get("subtitle"),"");if(title.length()>200||subtitle.length()>1500)throw new Api.Fail(400,"Tiêu đề quá dài");boolean attendance="attendance".equals(body.get("kind"));YearMonth month=null;if(attendance){try{month=YearMonth.parse(Objects.toString(body.get("month"),""));}catch(Exception e){throw new Api.Fail(400,"Tháng chấm công không hợp lệ");}if(cols!=4+month.lengthOfMonth()+7)throw new Api.Fail(400,"Số cột bảng công không đúng tháng");}
 try(var w=new XSSFWorkbook();var out=new ByteArrayOutputStream()){
 var s=w.createSheet(attendance?"Bảng chấm công":"Báo cáo");s.setDisplayGridlines(false);
 var header=style(w,true,"#E8F1FC",HorizontalAlignment.CENTER,null);var normal=style(w,false,null,HorizontalAlignment.LEFT,null);normal.setDataFormat(w.createDataFormat().getFormat("@"));var number=style(w,false,null,HorizontalAlignment.RIGHT,"#,##0;[Red]-#,##0");var decimal=style(w,false,null,HorizontalAlignment.RIGHT,"#,##0.0#;[Red]-#,##0.0#");var date=style(w,false,null,HorizontalAlignment.CENTER,"dd/mm/yyyy");var centered=style(w,false,null,HorizontalAlignment.CENTER,null);var yellow=style(w,false,"#FFF8CE",HorizontalAlignment.CENTER,null);var yellowHead=style(w,true,"#FFF1A6",HorizontalAlignment.CENTER,null);var total=style(w,true,"#E8F1FC",HorizontalAlignment.RIGHT,"#,##0;[Red]-#,##0");var titleStyle=style(w,true,null,HorizontalAlignment.CENTER,null);titleStyle.getFont().setFontHeightInPoints((short)18);titleStyle.setBorderTop(BorderStyle.NONE);titleStyle.setBorderBottom(BorderStyle.NONE);titleStyle.setBorderLeft(BorderStyle.NONE);titleStyle.setBorderRight(BorderStyle.NONE);
 var subtitleStyle=w.createCellStyle();subtitleStyle.cloneStyleFrom(titleStyle);var subtitleFont=w.createFont();subtitleFont.setFontName("Arial");subtitleFont.setFontHeightInPoints((short)11);subtitleStyle.setFont(subtitleFont);
 banner(s,0,cols,"VIGOO MOTOR • THU CHI VĨNH KHANG",titleStyle,28);banner(s,1,cols,title,titleStyle,34);banner(s,2,cols,subtitle,subtitleStyle,28);
 int head=4,start=attendance?6:5;var headRow=s.createRow(head);headRow.setHeightInPoints(attendance?35:40);Row daysRow=attendance?s.createRow(5):null;if(daysRow!=null)daysRow.setHeightInPoints(26);
 for(int c=0;c<cols;c++){String label=c<rows.getFirst().size()?Objects.toString(rows.getFirst().get(c),""):"";var cell=headRow.createCell(c);cell.setCellStyle(header);cell.setCellValue(label);if(attendance){var day=daysRow.createCell(c);day.setCellStyle(header);if(c>=4&&c<4+month.lengthOfMonth()){int n=c-3;boolean sunday=month.atDay(n).getDayOfWeek()==DayOfWeek.SUNDAY;cell.setCellValue(sunday?"CN":"T"+(month.atDay(n).getDayOfWeek().getValue()+1));day.setCellValue(String.format("%02d",n));if(sunday){cell.setCellStyle(yellowHead);day.setCellStyle(yellowHead);}}else s.addMergedRegion(new CellRangeAddress(4,5,c,c));}}
 int statusCol=-1;for(int c=0;c<rows.getFirst().size();c++)if("Trạng thái".equals(rows.getFirst().get(c)))statusCol=c;
 Set<Integer> sums=new HashSet<>();if(body.get("totalColumns") instanceof List<?> list)for(Object o:list){if(!(o instanceof Number n)||n.intValue()<0||n.intValue()>=cols)throw new Api.Fail(400,"Cột tổng không hợp lệ");sums.add(((Number)o).intValue());}
 for(int i=1;i<rows.size();i++){var r=s.createRow(start+i-1);r.setHeightInPoints(attendance?27:36);for(int c=0;c<cols;c++){Object value=c<rows.get(i).size()?rows.get(i).get(c):null;var cell=r.createCell(c);boolean sunday=attendance&&c>=4&&c<4+month.lengthOfMonth()&&month.atDay(c-3).getDayOfWeek()==DayOfWeek.SUNDAY;cell.setCellStyle(sunday?yellow:normal);if(value instanceof Number n){cell.setCellValue(n.doubleValue());cell.setCellStyle(n.doubleValue()%1==0?number:decimal);}else if(value instanceof Boolean b)cell.setCellValue(b?"Có":"Không");else if(value!=null){String t=value.toString();if(t.matches("\\d{4}-\\d{2}-\\d{2}")){try{cell.setCellValue(LocalDate.parse(t));cell.setCellStyle(date);}catch(Exception e){cell.setCellValue(t);}}else cell.setCellValue(t);}if(attendance&&c>=4&&c<4+month.lengthOfMonth())cell.setCellStyle(sunday?yellow:centered);}}
 int end=start+rows.size()-1;var footer=s.createRow(end);footer.setHeightInPoints(30);for(int c=0;c<cols;c++){var cell=footer.createCell(c);cell.setCellStyle(total);if(c==0)cell.setCellValue("TỔNG CỘNG");else if(sums.contains(c)&&rows.size()>1){String column=CellReference.convertNumToColString(c),range=column+(start+1)+":"+column+end;cell.setCellFormula(statusCol>=0?"SUMIFS("+range+","+CellReference.convertNumToColString(statusCol)+(start+1)+":"+CellReference.convertNumToColString(statusCol)+end+",\"<>Đã hủy\")":"SUM("+range+")");}else if(sums.contains(c))cell.setCellValue(0);}
 int firstSum=sums.stream().min(Integer::compare).orElse(cols);if(firstSum>1)s.addMergedRegion(new CellRangeAddress(end,end,0,firstSum-1));
 for(int c=0;c<cols;c++){String label=Objects.toString(rows.getFirst().get(c),"").toLowerCase(Locale.ROOT);int width=label.contains("nội dung")||label.contains("ghi chú")||label.contains("địa chỉ")?38:label.contains("tên")||label.contains("đối tác")||label.contains("nhân viên")?27:18;if(c==0&&label.equals("stt"))width=6;if(attendance&&c>=4&&c<4+month.lengthOfMonth())width=5;if(attendance&&c>=4+month.lengthOfMonth())width=15;s.setColumnWidth(c,width*256);}
 String note=attendance?"X = 1 công; ½ = nửa công; P = nghỉ phép có lương; KL = nghỉ không lương; N = nghỉ; ô trống = chưa chấm. Công Chủ nhật đã nằm trong công đi làm, không cộng thêm lần nữa. Tổng công = công đi làm + phép có lương. Chưa phân loại công lễ, Tết vì app chưa có lịch ngày lễ.":"Số tiền: đồng. Dòng tổng không tính phiếu đã hủy. Báo cáo theo dữ liệu và bộ lọc lúc xuất.";
 banner(s,end+2,cols,note,normal,42);int span=Math.max(1,cols/3);for(int i=0;i<3;i++){int first=i*span,last=i==2?cols-1:(i+1)*span-1;if(first>=cols)break;var r=s.getRow(end+4);if(r==null)r=s.createRow(end+4);var cell=r.createCell(first);cell.setCellValue(new String[]{attendance?"Người chấm công":"Người lập bảng","Kế toán trưởng","Giám đốc"}[i]);cell.setCellStyle(header);if(last>first)s.addMergedRegion(new CellRangeAddress(end+4,end+4,first,last));}s.createFreezePane(attendance?4:0,start);if(!attendance)s.setAutoFilter(new CellRangeAddress(head,Math.max(head,end-1),0,cols-1));s.setRepeatingRows(new CellRangeAddress(4,start-1,-1,-1));s.getPrintSetup().setLandscape(true);s.getPrintSetup().setPaperSize(attendance?PrintSetup.A3_PAPERSIZE:PrintSetup.A4_PAPERSIZE);s.getPrintSetup().setFitWidth((short)1);s.getPrintSetup().setFitHeight((short)0);s.setFitToPage(true);s.setPrintGridlines(false);s.setAutobreaks(true);s.getFooter().setRight("Trang &P / &N");w.setPrintArea(w.getSheetIndex(s),0,cols-1,0,end+7);w.getCreationHelper().createFormulaEvaluator().evaluateAll();var decimalTotal=w.createCellStyle();decimalTotal.cloneStyleFrom(total);decimalTotal.setDataFormat(decimal.getDataFormat());for(int c:sums){var cell=footer.getCell(c);if(cell.getCellType()==CellType.FORMULA&&cell.getCachedFormulaResultType()==CellType.NUMERIC&&cell.getNumericCellValue()%1!=0)cell.setCellStyle(decimalTotal);}w.write(out);return ResponseEntity.ok().contentType(MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")).body(out.toByteArray());
 }}
}
